def is_balanced(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in '([{':
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

def chunk_list(lst, n):
    if n <= 0:
        return []
    return [lst[i:i + n] for i in range(0, len(lst), n)]

